export function resolveCanonicalIntentionKey(raw, prayerId = null) {
  if (prayerId && PRAYER_ID_TO_CANONICAL[prayerId]) {
    return PRAYER_ID_TO_CANONICAL[prayerId];
  }
  if (!raw) return 'paz_interior';
  const str = String(raw).toLowerCase().trim();

  // 1. Claves directas
  if (str === 'proteccion' || str === 'liberacion') return 'proteccion';
  if (str === 'salud_sanacion' || str === 'sanacion_cuerpo' || str === 'salud' || str === 'sanacion') return 'salud_sanacion';
  if (str === 'paz_interior' || str === 'paz_serenidad' || str === 'paz' || str === 'amor_compasion' || str === 'familia' || str === 'familia_hogar' || str === 'humildad_paciencia') return 'paz_interior';
  if (str === 'prosperidad_trabajo' || str === 'prosperidad_abundancia' || str === 'prosperidad' || str === 'trabajo') return 'prosperidad_trabajo';
  if (str === 'sabiduria_guia' || str === 'justicia' || str === 'sabiduria' || str === 'guia') return 'sabiduria_guia';
  if (str === 'gratitud_alabanza' || str === 'gratitud_bendicion' || str === 'gratitud' || str === 'alabanza') return 'gratitud_alabanza';
  if (str === 'perdon_reconciliacion' || str === 'perdon_liberacion' || str === 'perdon' || str === 'reconciliacion') return 'perdon_reconciliacion';
  if (str === 'fortaleza_fe' || str === 'fortaleza_duelo' || str === 'consuelo_duelo' || str === 'fortaleza' || str === 'fe') return 'fortaleza_fe';

  // 2. Clasificador semántico multilingüe (17 idiomas)
  if (/salud|sanac|sanat|curac|cuerpo|enferm|medic|health|healing|sante|gueris|saude|cura\b|curar|salute|guarig|gesundheit|heilu|sanitas|sanatio|صحة|شفاء|चंगाई|आरोग्य|নিরাময়|स्वास्थ्य|исцелен|здоров|医治|健康|癒やし|kesembuhan|kesehatan|uponyaji|afya/i.test(str)) {
    return 'salud_sanacion';
  }
  if (/protec|resguard|amparo|defens|liberac|escudo|guerra_espiritual|exorc|blindaj|refugio|peligro|vigilancia|shelter|deliver|schutz|errett|protectio|защит|избавлен|حماي|تحصين|نجاة|حفظ|सुरक्षा|बचाव|মুক্তি|护佑|拯救|守護|救い|perlindung|pembebasan|ulinzi|ukombozi|הגנה|הצלה/i.test(str)) {
    return 'proteccion';
  }
  if (/prosper|trabaj|abund|sustent|cosech|empleo|negoc|dinero|prosperit|work|labor|abundanc|travail|trabalho|lavoro|wohlstand|arbeit|رزق|عمل|धन|समृद्धि|कार्य|কাজ|অর্থ|丰足|事业|繁栄|仕事|kemakmuran|pekerjaan|mafanikio|kazi|פרנסה|עבודה/i.test(str)) {
    return 'prosperidad_trabajo';
  }
  if (/sabidur|guia|discern|claridad|direcc|conocim|estudio|mente|ilumin|wisdom|guidance|sagesse|sabedor|orienta|sapienz|weisheit|fuehrung|directio|мудрост|наставлен|حكم|هداي|ज्ञान|मार्गदर्शन|বুদ্ধি|দীক্ষা|智慧|指引|知恵|導き|kebijaksanaan|panduan|hekima|mwongozo|חכמה|הדרכה|justicia|justice/i.test(str)) {
    return 'sabiduria_guia';
  }
  if (/gratitud|alaban|bendic|gloria|adorac|agradec|doxolog|magnificat|praise|bless|louang|gratidao|louvor|gratitudin|lode|dankbar|lob|laus|хвал|благодар|شكر|حمد|تسبيح|ثناء|स्तुति|कृतज्ञता|প্রশংসা|কৃতজ্ঞতা|赞美|感恩|感謝|賛美|syukur|pujian|shukrani|sifa|הודיה|שבח/i.test(str)) {
    return 'gratitud_alabanza';
  }
  if (/perdon|reconcil|arrepent|remis|misericord|forgiv|pardon|perdao|perdono|vergeb|versoehn|venia|прощен|примирен|مغفر|توب|عفو|क्षما|सुलह|প্রার্থনা|ক্ষমা|和解|宽恕|赦し|pengampunan|rekonsiliasi|msamaha|upatanisho|סליחה|מחילה/i.test(str)) {
    return 'perdon_reconciliacion';
  }
  if (/fortalez|fe\b|consuelo|esperanz|valenti|firmeza|pacienc|coraje|duelo|animo|perseveran|strength|faith|force|foi|forca|forza|fede|staerke|glaube|fortitudo|fides|стойкост|вер[аы]|сил[аы]|قوة|إيمان|صبر|शक्ति|विश्वास|ধৈর্য|ভরসা|力量|信心|強さ|信仰|kekuatan|iman|nguvu|imani|אמונה|עוצמה/i.test(str)) {
    return 'fortaleza_fe';
  }

  return 'paz_interior';
}
